def minPath(grid, k):
    from collections import deque

    n = len(grid)
    # Find the starting point (cell with value 1)
    start = None
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break
        if start:
            break

    # Directions for moving in the grid (up, down, left, right)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS to find the minimum path of length k
    queue = deque([(start, [1])])  # (current_position, current_path)
    visited = set()  # To prevent cycles
    while queue:
        (x, y), path = queue.popleft()

        # If the path length is k, return the path
        if len(path) == k:
            return path

        # Explore neighbors
        neighbors = sorted([((x + dx, y + dy), grid[x + dx][y + dy]) for dx, dy in directions
                            if 0 <= x + dx < n and 0 <= y + dy < n])
        for (nx, ny), neighbor_value in neighbors:
            if (nx, ny, len(path)+1) not in visited:
                visited.add((nx, ny, len(path)+1))
                new_path = path + [neighbor_value]
                queue.append(((nx, ny), new_path))

    return []  # Should never reach here due to problem guarantees

