def fizz_buzz(n: int):
    """Return the number of times the digit 7 appears in integers less than n which are divisible by 11 or 13."""
    unique_numbers = set()
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            unique_numbers.add(i)
    count = sum(str(num).count('7') for num in unique_numbers)
    return count

